INSERT INTO official_account_posts (post_id, account_id, title, summary, url, published_at) VALUES ('post_harbor_rules_0901', 'acct_harbor_master', 'Pier B group activity rules', 'Group sailing may use Pier B only with permit ID, confirmed manifest, and no drone launch.', 'mock://harbor/rules', '2026-08-24T08:06:00+08:00');
INSERT INTO official_account_posts (post_id, account_id, title, summary, url, published_at) VALUES ('post_weather_thresholds_0901', 'acct_marine_weather', 'Small craft thresholds', 'Small craft hold when active alert, lightning risk, sustained wind above 24 km/h, or wave clue above 1.0 m.', 'mock://weather/thresholds', '2026-08-24T08:07:00+08:00');
INSERT INTO notifications (notification_id, user_id, source, type, subscription_id, title, body, payload_json, created_at, read) VALUES ('ntf_initial_permit_pending', 'usr_sailing_ops', 'harbor-master', 'policy_update', NULL, 'Permit under review', 'Haiwan Pier B permit HP-0919 is pending. Final confirmation requires weather and insurance proof.', '{"permit":"HP-0919","status":"pending"}', '2026-08-24T08:08:00+08:00', 0);
INSERT INTO notifications (notification_id, user_id, source, type, subscription_id, title, body, payload_json, created_at, read) VALUES ('ntf_photo_policy', 'usr_sailing_ops', 'harbor-master', 'policy_update', NULL, 'Photo boundary', 'No drone launch, no marina staff close-ups, and no public-facing commercial shoot from Pier B without separate written approval.', '{"photo":"internal_only"}', '2026-08-24T08:09:00+08:00', 0);
INSERT INTO notifications (notification_id, user_id, source, type, subscription_id, title, body, payload_json, created_at, read) VALUES ('ntf_4k7m_harbor_closeout', 'usr_sailing_ops', 'harbor-master', 'policy_update', NULL, 'Pier A maintenance closeout', 'Pier A reopened after bollard inspection; the temporary loading restriction ended at 17:00. This notice concerns the May maintenance window, not a group permit.', '{"pier":"A","status":"reopened"}', '2026-05-12T17:18:00+08:00', 1);
INSERT INTO notifications (notification_id, user_id, source, type, subscription_id, title, body, payload_json, created_at, read) VALUES ('ntf_8p2c_wind_observation', 'usr_sailing_ops', 'marine-weather', 'weather_update', NULL, 'Afternoon sea-breeze observation', 'The June observation window recorded 21 km/h sustained wind and no active warning. It was an observation bulletin and did not authorize any specific activity.', '{"wind_kmh":21,"active_alert":false}', '2026-06-04T15:26:00+08:00', 1);
INSERT INTO notifications (notification_id, user_id, source, type, subscription_id, title, body, payload_json, created_at, read) VALUES ('ntf_r5w9_waiver_clinic', 'usr_sailing_ops', 'company-risk', 'policy_update', NULL, 'Waiver clinic completed', 'Twenty-three forms were checked at the June clinic; three incomplete forms were returned to employees and were not counted as cleared.', '{"reviewed":23,"returned":3}', '2026-06-05T18:07:00+08:00', 1);
INSERT INTO notifications (notification_id, user_id, source, type, subscription_id, title, body, payload_json, created_at, read) VALUES ('ntf_m3q8_shuttle_delay', 'usr_sailing_ops', 'facilities', 'traffic', NULL, 'West gate loading delay', 'A coach rehearsal took eleven extra minutes because equipment cases shared the passenger curb. Future manifests should assign a dispatcher and a separate carton load point.', '{"delay_minutes":11,"gate":"west"}', '2026-06-18T17:48:00+08:00', 1);
INSERT INTO notifications (notification_id, user_id, source, type, subscription_id, title, body, payload_json, created_at, read) VALUES ('ntf_t7b4_allergen_reply', 'usr_sailing_ops', 'wellbeing', 'policy_update', NULL, 'Kitchen allergen clarification', 'Tide Annex can plate a shellfish-free meal but cannot isolate its fryer. Catering records must remain with the event lead rather than the group channel.', '{"shellfish_free_plate":true,"separate_fryer":false}', '2026-06-24T10:12:00+08:00', 1);
INSERT INTO notifications (notification_id, user_id, source, type, subscription_id, title, body, payload_json, created_at, read) VALUES ('ntf_c6x1_gallery_expiry', 'usr_sailing_ops', 'hr-forms', 'policy_update', NULL, 'May gallery retention ended', 'The employee-portal gallery reached its 45-day retention date. Two withdrawn portraits were already removed; non-identifying venue images remain archived.', '{"retention_days":45,"removed_portraits":2}', '2026-07-01T13:40:00+08:00', 1);
INSERT INTO notifications (notification_id, user_id, source, type, subscription_id, title, body, payload_json, created_at, read) VALUES ('ntf_h9v2_claim_ready', 'usr_sailing_ops', 'guest-services', 'status_update', NULL, 'Lost-property item ready', 'A navy windbreaker is ready at Pier A reception under the original claim number. This closed case is unrelated to Pier B event planning.', '{"location":"Pier A reception","case_status":"closed"}', '2026-07-06T16:05:00+08:00', 1);
INSERT INTO notifications (notification_id, user_id, source, type, subscription_id, title, body, payload_json, created_at, read) VALUES ('ntf_q2n7_insurance_compare', 'usr_sailing_ops', 'insurance-desk', 'policy_update', NULL, 'Rowing quote comparison ready', 'The July comparison shows Harbor Basic capped at 20 named adults, while CrewSafe Group still requires a final manifest and issued certificate.', '{"harbor_basic_limit":20,"certificate_required":true}', '2026-07-09T10:51:00+08:00', 1);
INSERT INTO notifications (notification_id, user_id, source, type, subscription_id, title, body, payload_json, created_at, read) VALUES ('ntf_b4j6_contact_tree', 'usr_sailing_ops', 'security-operations', 'status_update', NULL, 'Emergency contact drill passed', 'Four coordinators acknowledged the drill within six minutes. The north reception extension was corrected in the restricted contact sheet.', '{"coordinators":4,"minutes":6}', '2026-07-14T16:19:00+08:00', 1);
INSERT INTO notifications (notification_id, user_id, source, type, subscription_id, title, body, payload_json, created_at, read) VALUES ('ntf_w8d3_thunder_cancel', 'usr_sailing_ops', 'marine-weather', 'weather_update', NULL, 'Client sail cancellation recorded', 'Lightning risk cancelled the July 22 client sail even though wind stayed moderate. The charter hold was released and the indoor dinner proceeded.', '{"reason":"lightning risk","charter_charge":0}', '2026-07-21T08:41:00+08:00', 0);
INSERT INTO notifications (notification_id, user_id, source, type, subscription_id, title, body, payload_json, created_at, read) VALUES ('ntf_f3s7_ledger_closed', 'usr_sailing_ops', 'finance-control', 'status_update', NULL, 'Northshore ledger reconciled', 'The Northshore offsite closed at CNY 46,780. A duplicate transport request for CNY 1,200 was voided before posting.', '{"spent_minor":4678000,"voided_minor":120000}', '2026-07-28T17:29:00+08:00', 0);
